computeFn:
const buy = Number(buyPrice) || 0;
const sell = Number(sellPrice) || 0;
const sh = Number(sharesHeld) || 0;
const rate = (Number(taxRatePct) || 0) / 100;
const gain = (sell - buy) * sh;
const tax = gain > 0 ? gain * rate : 0;
const netProfit = gain - tax;
const effRate = gain > 0 ? (tax / gain) * 100 : 0;
return { gain, tax, netProfit, effRate };
